layer.css:
@import url("https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,400;0,600;1,400&family=DM+Sans:wght@300;400;500&display=swap");
[data-ryt="footer"] { color: rgb(255, 255, 255); background-color: rgb(59, 92, 69); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="nav"] a { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-body); font-size: 14px; font-weight: 500; font-style: normal; line-height: 1.6; letter-spacing: 0.7px; text-transform: uppercase; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: color 0.3s }
[data-ryt="button"] { color: rgb(255, 255, 255); background-color: rgb(196, 113, 74); border-radius: 50%; box-shadow: rgba(0, 0, 0, 0.15) 0px 4px 12px 0px; font-family: Arial; font-weight: 400; font-style: normal; line-height: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(255, 255, 255); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: transform 0.2s, background-color 0.2s, box-shadow 0.2s }
[data-ryt="button"]:hover { transform: scale(1.1); box-shadow: rgba(0, 0, 0, 0.2) 0px 6px 20px }
[data-ryt="nav"] a:hover { color: #C4714A; color: #C4714A }
